const value = String($json.termino ?? '').trim();
if (!value) throw new Error('BOT_TOOL_INVALID_INPUT: se requiere un nombre o correo para buscar');
if (value.length > 200) throw new Error('BOT_TOOL_INVALID_INPUT: termino de busqueda demasiado largo');
return [{ json: { termino: value } }];
